head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[treeview > M > appendNode]<br/>트리 아이템 객체를 사용하여 특정 트리 아이템에 자식 아이템을 추가합니다.",
    "validation" : [
        "dynamicAppend=true 이고, 서로 다른 TreeView 컴포넌트인 경우 renderType 속성값이 동일한 경우에 동작합니다.",
        "parentNode(필수) 파라미터로 자식 아이템을 추가 하려는 트리 아이템을 객체로 설정합니다.",
        "childNode(필수) 파라미터로 자식 아이템으로 추가할 아이템을 객체로 설정합니다.",
        "parentNode 파라미터에 해당하는 트리 아이템의 마지막 자식으로 추가됩니다.",
        "parentNode(필수) 파라미터로 설정한 아이템에 자식 아이템이 있는 경우 모두 함께 추가됩니다.",
        "인덱스는 전체 트리 아이템의 마지막 인덱스부터 순서대로 설정됩니다.",
        "트리 아이템이 ItemSet 으로 정의된 경우 DataCollection 에 추가된 트리 아이템이 반영되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    if (typeof target2 !== 'undefined') {
        target2.remove();
    }

    let properties = {
        useDrag : true,        
    }

    let cList = $c.gcm.createCList(properties);    
    let eList = $c.gcm.createEList(["ondrop"], "target2");    

    // comp 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strTarget2 = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="상단 treeview 의 아이템을 하단 treeview 로 dragdrop 하여 확인(DataList 에 반영되지 않으므로 추가 할때마다 초기값 기준으로 추가됨)"', '', 'label1');

    strTarget += '<w2:treeview ' + strNameSpace + ' ' + cList + ' id="" dataType="listed" showCheckbox="true" style="position: relative;width: 200px; border: 1px solid blue;">';    
    strTarget += '<w2:itemset nodeset="data:dataList1">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '<w2:depth ref="depth"></w2:depth>';
    strTarget += '<w2:folder ref="folder"></w2:folder>';
    strTarget += '<w2:checkbox ref="checkbox"></w2:checkbox>';
    strTarget += '<w2:checkboxDisabled ref="disabled"></w2:checkboxDisabled>';
    strTarget += '<w2:image ref=""></w2:image>';
    strTarget += '<w2:iconImage ref=""></w2:iconImage>';
    strTarget += '<w2:selectedImage ref=""></w2:selectedImage>';
    strTarget += '<w2:expandedImage ref=""></w2:expandedImage>';
    strTarget += '<w2:leafImage ref=""></w2:leafImage>';
    strTarget += '</w2:itemset>';
    strTarget += '</w2:treeview>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "treeview",
        strTarget,
        grp_comp
    );

    strTarget2 += '<w2:treeview ' + strNameSpace + ' ' + eList + ' id="" dataType="listed" showCheckbox="true" style="position: relative;width: 200px; border: 1px solid red;">';    
    strTarget2 += '<w2:itemset nodeset="data:dataList2">';
    strTarget2 += '<w2:label ref="label"></w2:label>';
    strTarget2 += '<w2:value ref="value"></w2:value>';
    strTarget2 += '<w2:depth ref="depth"></w2:depth>';
    strTarget2 += '<w2:folder ref="folder"></w2:folder>';
    strTarget2 += '<w2:checkbox ref="checkbox"></w2:checkbox>';
    strTarget2 += '<w2:checkboxDisabled ref="disabled"></w2:checkboxDisabled>';
    strTarget2 += '<w2:image ref=""></w2:image>';
    strTarget2 += '<w2:iconImage ref=""></w2:iconImage>';
    strTarget2 += '<w2:selectedImage ref=""></w2:selectedImage>';
    strTarget2 += '<w2:expandedImage ref=""></w2:expandedImage>';
    strTarget2 += '<w2:leafImage ref=""></w2:leafImage>';
    strTarget2 += '</w2:itemset>';
    strTarget2 += '</w2:treeview>';

    // target 생성
    scwin.target2 = await $p.dynamicCreate(
        "target2",
        "treeview",
        strTarget2,
        grp_comp
    );
}



scwin.getDataList = function () {
    let rtn = dataList2.getRowCount();

    wf_body_bottom.getObj("scwin").setReturnValue("getRowCount : " + rtn);
}



scwin.getText = function () {
    let rtn = target2.render.textContent;

    wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);
}



scwin.target2_ondrop = function (dragNode, dropNode, dragComponent, dropComponent, e) {    
    this.appendNode(dropNode, dragNode);    // Drag 된 아이템 추가
    dragComponent.removeNode(dragNode);     // 복사된 아이템을 삭제

    scwin.getText();
    scwin.getDataList(); 
}
